INSERT INTO questions (mode, class_id, public, active, data, created_at) SELECT 1, NULL, 1, 1, '{"correct":"“Is the library open on Sundays?” asked Priya.\n“Not any more,” answered Mr Goh.","prompt":"“Is the library open on Sundays?” asked Priya. “Not any more,” answered Mr Goh.","alts":[],"lines":true,"instruction":"Give each speaker their own line.","tip":"A new speaker means a new line. It’s how readers keep track of who’s talking."}', 1792251314905 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE mode = 1 AND json_extract(data, '$.correct') = ('“Is the library open on Sundays?” asked Priya.' || char(10) || '“Not any more,” answered Mr Goh.'));
INSERT INTO questions (mode, class_id, public, active, data, created_at) SELECT 1, NULL, 1, 1, '{"correct":"“Have you seen my umbrella?” asked Kai.\n“It’s by the door,” said Nadia.","prompt":"“Have you seen my umbrella?” asked Kai. “It’s by the door,” said Nadia.","alts":[],"lines":true,"instruction":"Give each speaker their own line.","tip":"A new speaker means a new line. It’s how readers keep track of who’s talking."}', 1792251314905 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE mode = 1 AND json_extract(data, '$.correct') = ('“Have you seen my umbrella?” asked Kai.' || char(10) || '“It’s by the door,” said Nadia.'));
INSERT INTO questions (mode, class_id, public, active, data, created_at) SELECT 1, NULL, 1, 1, '{"correct":"“Who left the window open?” demanded Mrs Lee.\n“It wasn’t me,” whispered Danial.","prompt":"“Who left the window open?” demanded Mrs Lee. “It wasn’t me,” whispered Danial.","alts":[],"lines":true,"instruction":"Give each speaker their own line.","tip":"A new speaker means a new line. It’s how readers keep track of who’s talking."}', 1792251314905 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE mode = 1 AND json_extract(data, '$.correct') = ('“Who left the window open?” demanded Mrs Lee.' || char(10) || '“It wasn’t me,” whispered Danial.'));
INSERT INTO questions (mode, class_id, public, active, data, created_at) SELECT 1, NULL, 1, 1, '{"correct":"“Can we start the experiment now?” asked Hui Min.\n“Not until the goggles are on,” replied Mr Pillai.","prompt":"“Can we start the experiment now?” asked Hui Min. “Not until the goggles are on,” replied Mr Pillai.","alts":[],"lines":true,"instruction":"Give each speaker their own line.","tip":"A new speaker means a new line. It’s how readers keep track of who’s talking."}', 1792251314905 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE mode = 1 AND json_extract(data, '$.correct') = ('“Can we start the experiment now?” asked Hui Min.' || char(10) || '“Not until the goggles are on,” replied Mr Pillai.'));
INSERT INTO questions (mode, class_id, public, active, data, created_at) SELECT 1, NULL, 1, 1, '{"correct":"“Ready?” called Zara.\n“Ready!” shouted Omar.\n“Wait for me,” puffed Lily.","prompt":"“Ready?” called Zara. “Ready!” shouted Omar. “Wait for me,” puffed Lily.","alts":[],"lines":true,"instruction":"Give each speaker their own line.","tip":"A new speaker means a new line. It’s how readers keep track of who’s talking."}', 1792251314905 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE mode = 1 AND json_extract(data, '$.correct') = ('“Ready?” called Zara.' || char(10) || '“Ready!” shouted Omar.' || char(10) || '“Wait for me,” puffed Lily.'));
INSERT INTO questions (mode, class_id, public, active, data, created_at) SELECT 1, NULL, 1, 1, '{"correct":"Raj dropped his pencil. “Oh no, not again,” he sighed.","prompt":"raj dropped his pencil oh no not again he sighed","alts":[],"beat":true,"tip":"An action isn’t a saying verb, so that sentence ends with a full stop. The speech starts fresh with a capital letter."}', 1792251314905 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE mode = 1 AND json_extract(data, '$.correct') = ('Raj dropped his pencil. “Oh no, not again,” he sighed.'));
INSERT INTO questions (mode, class_id, public, active, data, created_at) SELECT 1, NULL, 1, 1, '{"correct":"Hana stamped her foot. “That isn’t fair!” she cried.","prompt":"hana stamped her foot that isn’t fair she cried","alts":[],"beat":true,"tip":"An action isn’t a saying verb, so that sentence ends with a full stop. The speech starts fresh with a capital letter."}', 1792251314905 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE mode = 1 AND json_extract(data, '$.correct') = ('Hana stamped her foot. “That isn’t fair!” she cried.'));
INSERT INTO questions (mode, class_id, public, active, data, created_at) SELECT 1, NULL, 1, 1, '{"correct":"The teacher glanced at the door. “Who is there?” she asked.","prompt":"the teacher glanced at the door who is there she asked","alts":[],"beat":true,"tip":"An action isn’t a saying verb, so that sentence ends with a full stop. The speech starts fresh with a capital letter."}', 1792251314905 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE mode = 1 AND json_extract(data, '$.correct') = ('The teacher glanced at the door. “Who is there?” she asked.'));
INSERT INTO questions (mode, class_id, public, active, data, created_at) SELECT 1, NULL, 1, 1, '{"correct":"Ben grinned at his sister. “You’ll never catch me,” he teased.","prompt":"ben grinned at his sister you’ll never catch me he teased","alts":[],"beat":true,"tip":"An action isn’t a saying verb, so that sentence ends with a full stop. The speech starts fresh with a capital letter."}', 1792251314905 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE mode = 1 AND json_extract(data, '$.correct') = ('Ben grinned at his sister. “You’ll never catch me,” he teased.'));
INSERT INTO questions (mode, class_id, public, active, data, created_at) SELECT 1, NULL, 1, 1, '{"correct":"Farah shut her book. “That was the best chapter yet,” she announced.","prompt":"farah shut her book that was the best chapter yet she announced","alts":[],"beat":true,"tip":"An action isn’t a saying verb, so that sentence ends with a full stop. The speech starts fresh with a capital letter."}', 1792251314905 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE mode = 1 AND json_extract(data, '$.correct') = ('Farah shut her book. “That was the best chapter yet,” she announced.'));
INSERT INTO questions (mode, class_id, public, active, data, created_at) SELECT 4, NULL, 1, 1, '{"stem":"“I can’t believe we won!” said the captain. Which verb is the best upgrade for “said”?","options":[{"id":"a","text":"cheered"},{"id":"b","text":"muttered","why":"Muttering is low and grumpy. The captain is thrilled."},{"id":"c","text":"sighed","why":"A sigh shows tiredness or disappointment, not joy."},{"id":"d","text":"grumbled","why":"Grumbling is a complaint. Winning is good news."}],"correct":["a"],"pick":1,"explanation":"Winning is exciting news, so the captain shouts with joy. Cheered shows both the volume and the happiness.","code":"MC_VERB"}', 1792251314905 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE mode = 4 AND json_extract(data, '$.stem') = ('“I can’t believe we won!” said the captain. Which verb is the best upgrade for “said”?') AND COALESCE(json_extract(data, '$.context'), '') = (''));
INSERT INTO questions (mode, class_id, public, active, data, created_at) SELECT 4, NULL, 1, 1, '{"stem":"“Please don’t leave me here,” said the little boy. Which verb is the best upgrade for “said”?","options":[{"id":"a","text":"pleaded"},{"id":"b","text":"boasted","why":"Boasting is showing off. The boy is frightened."},{"id":"c","text":"announced","why":"Announcing is loud and confident. He is begging."},{"id":"d","text":"snapped","why":"Snapping is sharp and cross. He is scared, not angry."}],"correct":["a"],"pick":1,"explanation":"He is frightened and begging someone to stay. Pleaded shows the fear and the request.","code":"MC_VERB"}', 1792251314905 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE mode = 4 AND json_extract(data, '$.stem') = ('“Please don’t leave me here,” said the little boy. Which verb is the best upgrade for “said”?') AND COALESCE(json_extract(data, '$.context'), '') = (''));
INSERT INTO questions (mode, class_id, public, active, data, created_at) SELECT 4, NULL, 1, 1, '{"stem":"“That was the funniest thing I’ve ever seen,” said Ana. Which verb is the best upgrade for “said”?","options":[{"id":"a","text":"giggled"},{"id":"b","text":"warned","why":"A warning is about danger. Nothing here is dangerous."},{"id":"c","text":"groaned","why":"A groan shows pain or annoyance, not delight."},{"id":"d","text":"demanded","why":"Demanding is forceful. Ana is amused, not bossy."}],"correct":["a"],"pick":1,"explanation":"Ana found it hilarious, so a laughing verb fits. Giggled shows her amusement.","code":"MC_VERB"}', 1792251314905 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE mode = 4 AND json_extract(data, '$.stem') = ('“That was the funniest thing I’ve ever seen,” said Ana. Which verb is the best upgrade for “said”?') AND COALESCE(json_extract(data, '$.context'), '') = (''));
INSERT INTO questions (mode, class_id, public, active, data, created_at) SELECT 4, NULL, 1, 1, '{"stem":"“Don’t touch that wire,” said the electrician. Which verb is the best upgrade for “said”?","options":[{"id":"a","text":"warned"},{"id":"b","text":"giggled","why":"Giggling is playful. This is serious."},{"id":"c","text":"boasted","why":"Boasting is showing off. This is about safety."},{"id":"d","text":"wondered","why":"Wondering is an uncertain thought. The electrician is giving an order."}],"correct":["a"],"pick":1,"explanation":"The electrician is telling someone to avoid danger. Warned shows the seriousness of the message.","code":"MC_VERB"}', 1792251314905 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE mode = 4 AND json_extract(data, '$.stem') = ('“Don’t touch that wire,” said the electrician. Which verb is the best upgrade for “said”?') AND COALESCE(json_extract(data, '$.context'), '') = (''));
INSERT INTO questions (mode, class_id, public, active, data, created_at) SELECT 4, NULL, 1, 1, '{"stem":"“I think I heard a noise downstairs,” said Mei. Which verb is the best upgrade for “said”?","options":[{"id":"a","text":"whispered"},{"id":"b","text":"bellowed","why":"Bellowing is very loud. It would give her hiding place away."},{"id":"c","text":"boasted","why":"Boasting is showing off. Mei is worried."},{"id":"d","text":"cheered","why":"Cheering shows joy. A strange noise is not good news."}],"correct":["a"],"pick":1,"explanation":"Mei is nervous and does not want to be heard. Whispered shows the quiet voice and the fear.","code":"MC_VERB"}', 1792251314905 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE mode = 4 AND json_extract(data, '$.stem') = ('“I think I heard a noise downstairs,” said Mei. Which verb is the best upgrade for “said”?') AND COALESCE(json_extract(data, '$.context'), '') = (''));
INSERT INTO questions (mode, class_id, public, active, data, created_at) SELECT 5, NULL, 1, 1, '{"prompt":"“We are late for the bus,” said Imran.","instruction":"Rewrite as reported speech.","accepted":["Imran said (that) they were late for the bus."],"tip":"In reported speech the tense steps back (are becomes were) and we becomes they."}', 1792251314905 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE mode = 5 AND json_extract(data, '$.prompt') = ('“We are late for the bus,” said Imran.') AND json_extract(data, '$.instruction') = ('Rewrite as reported speech.'));
INSERT INTO questions (mode, class_id, public, active, data, created_at) SELECT 5, NULL, 1, 1, '{"prompt":"“I will help you tomorrow,” Mei said to Raj.","instruction":"Rewrite as reported speech.","accepted":["Mei [told|said to] Raj (that) she would help him [the next day|the following day].","Mei said (that) she would help Raj [the next day|the following day]."],"tip":"Will steps back to would, I becomes she, you becomes him, and tomorrow becomes the next day."}', 1792251314905 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE mode = 5 AND json_extract(data, '$.prompt') = ('“I will help you tomorrow,” Mei said to Raj.') AND json_extract(data, '$.instruction') = ('Rewrite as reported speech.'));
INSERT INTO questions (mode, class_id, public, active, data, created_at) SELECT 5, NULL, 1, 1, '{"prompt":"“I am reading a funny book,” said Dan.","instruction":"Rewrite as reported speech.","accepted":["Dan said (that) he was reading a funny book."],"tip":"Am reading steps back to was reading, and I becomes he."}', 1792251314905 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE mode = 5 AND json_extract(data, '$.prompt') = ('“I am reading a funny book,” said Dan.') AND json_extract(data, '$.instruction') = ('Rewrite as reported speech.'));
INSERT INTO questions (mode, class_id, public, active, data, created_at) SELECT 5, NULL, 1, 1, '{"prompt":"“The shop closes at six,” said Mrs Tan.","instruction":"Rewrite as reported speech.","accepted":["Mrs Tan said (that) the shop closed at six."],"tip":"The verb steps back in time: closes becomes closed."}', 1792251314905 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE mode = 5 AND json_extract(data, '$.prompt') = ('“The shop closes at six,” said Mrs Tan.') AND json_extract(data, '$.instruction') = ('Rewrite as reported speech.'));
INSERT INTO questions (mode, class_id, public, active, data, created_at) SELECT 5, NULL, 1, 1, '{"prompt":"“I have finished my homework,” said Hana.","instruction":"Rewrite as reported speech.","accepted":["Hana said (that) she had finished her homework."],"tip":"Have finished steps back to had finished, and I and my become she and her."}', 1792251314905 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE mode = 5 AND json_extract(data, '$.prompt') = ('“I have finished my homework,” said Hana.') AND json_extract(data, '$.instruction') = ('Rewrite as reported speech.'));
INSERT INTO questions (mode, class_id, public, active, data, created_at) SELECT 5, NULL, 1, 1, '{"prompt":"Kai told Lena that he was hungry.","instruction":"Rewrite as direct speech.","accepted":["Kai [said to|told] Lena, “I[ am|’m] hungry.”"],"tip":"Go back to the speaker’s own words: he was becomes I am. Put them in speech marks after a comma."}', 1792251314905 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE mode = 5 AND json_extract(data, '$.prompt') = ('Kai told Lena that he was hungry.') AND json_extract(data, '$.instruction') = ('Rewrite as direct speech.'));
INSERT INTO questions (mode, class_id, public, active, data, created_at) SELECT 5, NULL, 1, 1, '{"prompt":"Mr Lim said that the bus had left.","instruction":"Rewrite as direct speech.","accepted":["Mr Lim said, “The bus has left.”","“The bus has left,” said Mr Lim.","“The bus has left,” Mr Lim said."],"tip":"Go back to the speaker’s own words: had left becomes has left."}', 1792251314905 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE mode = 5 AND json_extract(data, '$.prompt') = ('Mr Lim said that the bus had left.') AND json_extract(data, '$.instruction') = ('Rewrite as direct speech.'));
INSERT INTO questions (mode, class_id, public, active, data, created_at) SELECT 5, NULL, 1, 1, '{"prompt":"Nadia told Omar that she would meet him the next day.","instruction":"Rewrite as direct speech.","accepted":["Nadia [said to|told] Omar, “I[ will|’ll] meet you tomorrow.”"],"tip":"she would becomes I will, him becomes you, and the next day becomes tomorrow."}', 1792251314905 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE mode = 5 AND json_extract(data, '$.prompt') = ('Nadia told Omar that she would meet him the next day.') AND json_extract(data, '$.instruction') = ('Rewrite as direct speech.'));
INSERT INTO questions (mode, class_id, public, active, data, created_at) SELECT 5, NULL, 1, 1, '{"prompt":"Zack said that he was going to the park.","instruction":"Rewrite as direct speech.","accepted":["Zack said, “I[ am|’m] going to the park.”","“I[ am|’m] going to the park,” said Zack."],"tip":"Go back to the speaker’s own words: he was going becomes I am going."}', 1792251314905 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE mode = 5 AND json_extract(data, '$.prompt') = ('Zack said that he was going to the park.') AND json_extract(data, '$.instruction') = ('Rewrite as direct speech.'));
INSERT INTO questions (mode, class_id, public, active, data, created_at) SELECT 5, NULL, 1, 1, '{"prompt":"Hui Min told Raj that she had lost her key.","instruction":"Rewrite as direct speech.","accepted":["Hui Min [said to|told] Raj, “I[ have|’ve] lost my key.”"],"tip":"she had lost becomes I have lost, and her becomes my."}', 1792251314905 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE mode = 5 AND json_extract(data, '$.prompt') = ('Hui Min told Raj that she had lost her key.') AND json_extract(data, '$.instruction') = ('Rewrite as direct speech.'));
INSERT INTO questions (mode, class_id, public, active, data, created_at) SELECT 6, NULL, 1, 1, '{"sentence":"The pirates sailed across the bay and find a hidden cave.","wrong":["find"],"fixes":["found"],"tip":"Keep the verbs in the same time. The story is in the past, so find should be found."}', 1792251314905 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE mode = 6 AND json_extract(data, '$.sentence') = ('The pirates sailed across the bay and find a hidden cave.'));
INSERT INTO questions (mode, class_id, public, active, data, created_at) SELECT 6, NULL, 1, 1, '{"sentence":"Mei opened the door and walks into the dark room.","wrong":["walks"],"fixes":["walked"],"tip":"Keep the verbs in the same time. Opened is in the past, so walks should be walked."}', 1792251314905 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE mode = 6 AND json_extract(data, '$.sentence') = ('Mei opened the door and walks into the dark room.'));
INSERT INTO questions (mode, class_id, public, active, data, created_at) SELECT 6, NULL, 1, 1, '{"sentence":"Yesterday the class visited the museum and learn about dinosaurs.","wrong":["learn"],"fixes":["learned","learnt"],"tip":"Yesterday tells us this is in the past, so learn should be learned (or learnt)."}', 1792251314905 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE mode = 6 AND json_extract(data, '$.sentence') = ('Yesterday the class visited the museum and learn about dinosaurs.'));
INSERT INTO questions (mode, class_id, public, active, data, created_at) SELECT 6, NULL, 1, 1, '{"sentence":"The dragon roared, shakes its wings and flew away.","wrong":["shakes"],"fixes":["shook"],"tip":"Roared and flew are in the past, so shakes should be shook."}', 1792251314905 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE mode = 6 AND json_extract(data, '$.sentence') = ('The dragon roared, shakes its wings and flew away.'));
INSERT INTO questions (mode, class_id, public, active, data, created_at) SELECT 6, NULL, 1, 1, '{"sentence":"Raj picked up the letter and reads it slowly.","wrong":["reads"],"fixes":["read"],"tip":"Picked up is in the past, so reads should be read (said “red”)."}', 1792251314905 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE mode = 6 AND json_extract(data, '$.sentence') = ('Raj picked up the letter and reads it slowly.'));
INSERT INTO questions (mode, class_id, public, active, data, created_at) SELECT 4, NULL, 1, 1, '{"stem":"How does Tomas really feel?","options":[{"id":"a","text":"confident","why":"He says so, but his actions say otherwise."},{"id":"b","text":"scared but hiding it"},{"id":"c","text":"sleepy","why":"Nothing in the passage suggests he is tired."},{"id":"d","text":"annoyed that Pia is late","why":"Pia is already there holding the light."}],"correct":["b"],"pick":1,"explanation":"He says he does not need a torch, but he grips the railing and will not take a step. He is scared and does not want to admit it.","code":"MC_INFER","context":"“I don’t need a torch,” said Tomas, gripping the railing.\nPia held the light steady. “The stairs are very dark, though.”\n“I said I’m fine,” Tomas replied, but he did not take a step.","group":"rbtl-tomas"}', 1792251314905 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE mode = 4 AND json_extract(data, '$.stem') = ('How does Tomas really feel?') AND COALESCE(json_extract(data, '$.context'), '') = ('“I don’t need a torch,” said Tomas, gripping the railing.' || char(10) || 'Pia held the light steady. “The stairs are very dark, though.”' || char(10) || '“I said I’m fine,” Tomas replied, but he did not take a step.'));
INSERT INTO questions (mode, class_id, public, active, data, created_at) SELECT 4, NULL, 1, 1, '{"stem":"Which TWO details show he is not as brave as he says?","options":[{"id":"a","text":"He is gripping the railing."},{"id":"b","text":"He does not take a step."},{"id":"c","text":"He says again that he is fine."},{"id":"d","text":"Pia holds the light steady.","why":"This shows what Pia does, not how Tomas feels."},{"id":"e","text":"The stairs are very dark.","why":"This describes the place, not how Tomas behaves."},{"id":"f","text":"Tomas speaks to Pia.","why":"Speaking tells us nothing about his feelings."}],"correct":["a","b","c"],"pick":2,"explanation":"Gripping the railing, refusing to move and insisting a second time that he is fine all show fear. The light, the dark stairs and the fact that he speaks do not.","code":"MC_INFER","context":"“I don’t need a torch,” said Tomas, gripping the railing.\nPia held the light steady. “The stairs are very dark, though.”\n“I said I’m fine,” Tomas replied, but he did not take a step.","group":"rbtl-tomas"}', 1792251314905 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE mode = 4 AND json_extract(data, '$.stem') = ('Which TWO details show he is not as brave as he says?') AND COALESCE(json_extract(data, '$.context'), '') = ('“I don’t need a torch,” said Tomas, gripping the railing.' || char(10) || 'Pia held the light steady. “The stairs are very dark, though.”' || char(10) || '“I said I’m fine,” Tomas replied, but he did not take a step.'));
INSERT INTO questions (mode, class_id, public, active, data, created_at) SELECT 4, NULL, 1, 1, '{"stem":"Why does Pia say, “The stairs are very dark, though”?","options":[{"id":"a","text":"To gently show she has noticed he might need the light"},{"id":"b","text":"To warn him that she is leaving","why":"She stays and holds the light steady."},{"id":"c","text":"To boast that she is not afraid","why":"Nothing she says is about herself."},{"id":"d","text":"To complain about the electricity","why":"She is talking about the stairs, not complaining."}],"correct":["a"],"pick":1,"explanation":"The word though shows she does not quite believe him. She is offering help without teasing him.","code":"MC_INFER","context":"“I don’t need a torch,” said Tomas, gripping the railing.\nPia held the light steady. “The stairs are very dark, though.”\n“I said I’m fine,” Tomas replied, but he did not take a step.","group":"rbtl-tomas"}', 1792251314905 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE mode = 4 AND json_extract(data, '$.stem') = ('Why does Pia say, “The stairs are very dark, though”?') AND COALESCE(json_extract(data, '$.context'), '') = ('“I don’t need a torch,” said Tomas, gripping the railing.' || char(10) || 'Pia held the light steady. “The stairs are very dark, though.”' || char(10) || '“I said I’m fine,” Tomas replied, but he did not take a step.'));
INSERT INTO questions (mode, class_id, public, active, data, created_at) SELECT 4, NULL, 1, 1, '{"stem":"How does Hana really feel after the match?","options":[{"id":"a","text":"delighted","why":"A delighted player would not hide under her cap."},{"id":"b","text":"disappointed but pretending not to care"},{"id":"c","text":"relaxed","why":"A relaxed person would not avoid looking at anyone."},{"id":"d","text":"jealous of Dev","why":"Dev is kind to her, and nothing suggests jealousy."}],"correct":["b"],"pick":1,"explanation":"She says it does not matter, but she stares at the scoreboard, answers with one word and hides under her cap. She cares a lot.","code":"MC_INFER","context":"“It doesn’t matter,” said Hana, shrugging. She kept her eyes on the empty scoreboard.\nDev nudged her. “You played brilliantly, you know.”\n“Mm,” Hana said, and pulled her cap lower.","group":"rbtl-hana"}', 1792251314905 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE mode = 4 AND json_extract(data, '$.stem') = ('How does Hana really feel after the match?') AND COALESCE(json_extract(data, '$.context'), '') = ('“It doesn’t matter,” said Hana, shrugging. She kept her eyes on the empty scoreboard.' || char(10) || 'Dev nudged her. “You played brilliantly, you know.”' || char(10) || '“Mm,” Hana said, and pulled her cap lower.'));
INSERT INTO questions (mode, class_id, public, active, data, created_at) SELECT 4, NULL, 1, 1, '{"stem":"Which TWO details suggest the result matters to Hana?","options":[{"id":"a","text":"She keeps her eyes on the scoreboard."},{"id":"b","text":"She pulls her cap lower."},{"id":"c","text":"She answers with only “Mm”."},{"id":"d","text":"Dev nudges her.","why":"This is what Dev does, not Hana."},{"id":"e","text":"Dev says she played brilliantly.","why":"This is Dev’s opinion, not a clue about Hana."},{"id":"f","text":"The scoreboard is mentioned.","why":"It matters only because Hana will not stop looking at it."}],"correct":["a","b","c"],"pick":2,"explanation":"Staring at the scoreboard, hiding under her cap and giving a one-word reply all show she is upset. Dev’s nudge and praise show how Dev feels.","code":"MC_INFER","context":"“It doesn’t matter,” said Hana, shrugging. She kept her eyes on the empty scoreboard.\nDev nudged her. “You played brilliantly, you know.”\n“Mm,” Hana said, and pulled her cap lower.","group":"rbtl-hana"}', 1792251314905 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE mode = 4 AND json_extract(data, '$.stem') = ('Which TWO details suggest the result matters to Hana?') AND COALESCE(json_extract(data, '$.context'), '') = ('“It doesn’t matter,” said Hana, shrugging. She kept her eyes on the empty scoreboard.' || char(10) || 'Dev nudged her. “You played brilliantly, you know.”' || char(10) || '“Mm,” Hana said, and pulled her cap lower.'));
INSERT INTO questions (mode, class_id, public, active, data, created_at) SELECT 4, NULL, 1, 1, '{"stem":"Why does Dev nudge Hana and praise her?","options":[{"id":"a","text":"To comfort her and show he has noticed she is upset"},{"id":"b","text":"To tease her about losing","why":"His words are kind, not teasing."},{"id":"c","text":"To take the credit for the match","why":"Dev says she played well, not himself."},{"id":"d","text":"To end the conversation","why":"Praise invites her to talk."}],"correct":["a"],"pick":1,"explanation":"A nudge and a kind word are what a friend does when he can tell someone is hurting.","code":"MC_INFER","context":"“It doesn’t matter,” said Hana, shrugging. She kept her eyes on the empty scoreboard.\nDev nudged her. “You played brilliantly, you know.”\n“Mm,” Hana said, and pulled her cap lower.","group":"rbtl-hana"}', 1792251314905 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE mode = 4 AND json_extract(data, '$.stem') = ('Why does Dev nudge Hana and praise her?') AND COALESCE(json_extract(data, '$.context'), '') = ('“It doesn’t matter,” said Hana, shrugging. She kept her eyes on the empty scoreboard.' || char(10) || 'Dev nudged her. “You played brilliantly, you know.”' || char(10) || '“Mm,” Hana said, and pulled her cap lower.'));
INSERT INTO questions (mode, class_id, public, active, data, created_at) SELECT 4, NULL, 1, 1, '{"stem":"How does Zane really feel?","options":[{"id":"a","text":"relaxed","why":"A relaxed person would not tap and shake."},{"id":"b","text":"nervous but denying it"},{"id":"c","text":"cold and nothing else","why":"He offers the cold as an excuse for his shaking hands."},{"id":"d","text":"bored","why":"Boredom would not make his hands shake."}],"correct":["b"],"pick":1,"explanation":"He says he is not nervous, but he taps his foot, his hands shake and he hides them. The cold is only an excuse.","code":"MC_INFER","context":"“I’m not nervous,” said Zane, tapping his foot against the chair leg.\nMum smiled. “Your hands are shaking.”\nZane hid them under his legs. “It’s cold in here.”","group":"rbtl-zane"}', 1792251314905 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE mode = 4 AND json_extract(data, '$.stem') = ('How does Zane really feel?') AND COALESCE(json_extract(data, '$.context'), '') = ('“I’m not nervous,” said Zane, tapping his foot against the chair leg.' || char(10) || 'Mum smiled. “Your hands are shaking.”' || char(10) || 'Zane hid them under his legs. “It’s cold in here.”'));
INSERT INTO questions (mode, class_id, public, active, data, created_at) SELECT 4, NULL, 1, 1, '{"stem":"Which TWO details show Zane is nervous?","options":[{"id":"a","text":"He taps his foot against the chair."},{"id":"b","text":"He hides his shaking hands."},{"id":"c","text":"He says it is cold in the room."},{"id":"d","text":"Mum smiles.","why":"This is what Mum does, not Zane."},{"id":"e","text":"Mum speaks to him.","why":"Mum speaking is not a clue about Zane."},{"id":"f","text":"He is sitting on a chair.","why":"Sitting says nothing about nerves."}],"correct":["a","b","c"],"pick":2,"explanation":"Foot-tapping, hiding his hands and blaming the cold all point to nerves. Mum smiling or speaking, and the chair, do not.","code":"MC_INFER","context":"“I’m not nervous,” said Zane, tapping his foot against the chair leg.\nMum smiled. “Your hands are shaking.”\nZane hid them under his legs. “It’s cold in here.”","group":"rbtl-zane"}', 1792251314905 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE mode = 4 AND json_extract(data, '$.stem') = ('Which TWO details show Zane is nervous?') AND COALESCE(json_extract(data, '$.context'), '') = ('“I’m not nervous,” said Zane, tapping his foot against the chair leg.' || char(10) || 'Mum smiled. “Your hands are shaking.”' || char(10) || 'Zane hid them under his legs. “It’s cold in here.”'));
INSERT INTO questions (mode, class_id, public, active, data, created_at) SELECT 4, NULL, 1, 1, '{"stem":"Why does Mum smile before she speaks?","options":[{"id":"a","text":"To show she is kind and is not cross with him"},{"id":"b","text":"To laugh at his shaking hands","why":"Nothing in the passage suggests she is mocking him."},{"id":"c","text":"To pretend she has not noticed","why":"She goes on to mention his hands."},{"id":"d","text":"To show she is bored","why":"She is paying close attention to him."}],"correct":["a"],"pick":1,"explanation":"Her smile makes what she says gentle. She has noticed his nerves and wants him to feel safe.","code":"MC_INFER","context":"“I’m not nervous,” said Zane, tapping his foot against the chair leg.\nMum smiled. “Your hands are shaking.”\nZane hid them under his legs. “It’s cold in here.”","group":"rbtl-zane"}', 1792251314905 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE mode = 4 AND json_extract(data, '$.stem') = ('Why does Mum smile before she speaks?') AND COALESCE(json_extract(data, '$.context'), '') = ('“I’m not nervous,” said Zane, tapping his foot against the chair leg.' || char(10) || 'Mum smiled. “Your hands are shaking.”' || char(10) || 'Zane hid them under his legs. “It’s cold in here.”'));
INSERT INTO questions (mode, class_id, public, active, data, created_at) SELECT 4, NULL, 1, 1, '{"stem":"How does Lee really feel about Mina’s trophy?","options":[{"id":"a","text":"proud of her","why":"Proud people sound warm, not flat."},{"id":"b","text":"jealous but pretending to be pleased"},{"id":"c","text":"confused by the news","why":"He is not asking questions."},{"id":"d","text":"sleepy","why":"Nothing suggests he is tired."}],"correct":["b"],"pick":1,"explanation":"Slow clapping, a flat voice and turning away show he is not truly happy for her. He is jealous.","code":"MC_INFER","context":"“Great news,” said Lee, clapping slowly. “Another trophy for Mina.”\nMina’s smile faded. “You could sound happier about it.”\nLee looked out of the window instead of answering.","group":"rbtl-lee"}', 1792251314905 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE mode = 4 AND json_extract(data, '$.stem') = ('How does Lee really feel about Mina’s trophy?') AND COALESCE(json_extract(data, '$.context'), '') = ('“Great news,” said Lee, clapping slowly. “Another trophy for Mina.”' || char(10) || 'Mina’s smile faded. “You could sound happier about it.”' || char(10) || 'Lee looked out of the window instead of answering.'));
INSERT INTO questions (mode, class_id, public, active, data, created_at) SELECT 4, NULL, 1, 1, '{"stem":"Which TWO details show Lee is not sincere?","options":[{"id":"a","text":"He claps slowly."},{"id":"b","text":"He looks out of the window instead of answering."},{"id":"c","text":"He says “Another trophy for Mina” in a flat way."},{"id":"d","text":"Mina’s smile fades.","why":"This shows how Mina feels, not Lee."},{"id":"e","text":"Mina speaks to him.","why":"Mina speaking is not a clue about Lee."},{"id":"f","text":"The news is mentioned.","why":"The news is the reason, not a clue about how Lee feels."}],"correct":["a","b","c"],"pick":2,"explanation":"Slow clapping, a flat remark and refusing to look at her all show he does not mean it. Mina’s reaction shows she noticed.","code":"MC_INFER","context":"“Great news,” said Lee, clapping slowly. “Another trophy for Mina.”\nMina’s smile faded. “You could sound happier about it.”\nLee looked out of the window instead of answering.","group":"rbtl-lee"}', 1792251314905 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE mode = 4 AND json_extract(data, '$.stem') = ('Which TWO details show Lee is not sincere?') AND COALESCE(json_extract(data, '$.context'), '') = ('“Great news,” said Lee, clapping slowly. “Another trophy for Mina.”' || char(10) || 'Mina’s smile faded. “You could sound happier about it.”' || char(10) || 'Lee looked out of the window instead of answering.'));
INSERT INTO questions (mode, class_id, public, active, data, created_at) SELECT 4, NULL, 1, 1, '{"stem":"Why does Mina say, “You could sound happier about it”?","options":[{"id":"a","text":"Because she can tell his words and clapping are not sincere"},{"id":"b","text":"Because she did not hear what he said","why":"She heard well enough to answer him."},{"id":"c","text":"Because she wants him to be louder","why":"She is talking about his feelings, not his volume."},{"id":"d","text":"Because she is bored of the trophy","why":"Her smile only fades after Lee speaks."}],"correct":["a"],"pick":1,"explanation":"Her smile fades because she has seen through him. She is gently pointing out that he does not sound pleased.","code":"MC_INFER","context":"“Great news,” said Lee, clapping slowly. “Another trophy for Mina.”\nMina’s smile faded. “You could sound happier about it.”\nLee looked out of the window instead of answering.","group":"rbtl-lee"}', 1792251314905 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE mode = 4 AND json_extract(data, '$.stem') = ('Why does Mina say, “You could sound happier about it”?') AND COALESCE(json_extract(data, '$.context'), '') = ('“Great news,” said Lee, clapping slowly. “Another trophy for Mina.”' || char(10) || 'Mina’s smile faded. “You could sound happier about it.”' || char(10) || 'Lee looked out of the window instead of answering.'));
INSERT INTO questions (mode, class_id, public, active, data, created_at) SELECT 4, NULL, 1, 1, '{"stem":"How does Grandpa really feel?","options":[{"id":"a","text":"cheerful","why":"A cheerful person would not keep fiddling with a photo."},{"id":"b","text":"lonely but not wanting to say so"},{"id":"c","text":"angry that Nora has arrived","why":"He does not tell her to leave."},{"id":"d","text":"hungry","why":"Food is never mentioned."}],"correct":["b"],"pick":1,"explanation":"He tells her not to fuss, but he keeps touching the photo, has been up since five and says the house is quiet. He is lonely.","code":"MC_INFER","context":"“Don’t fuss,” said Grandpa, straightening the photo on the shelf for the third time.\nNora set down her bag. “You’ve been up since five, haven’t you?”\n“The house is just quiet,” he said, and turned the photo to face the chair again.","group":"rbtl-grandpa"}', 1792251314905 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE mode = 4 AND json_extract(data, '$.stem') = ('How does Grandpa really feel?') AND COALESCE(json_extract(data, '$.context'), '') = ('“Don’t fuss,” said Grandpa, straightening the photo on the shelf for the third time.' || char(10) || 'Nora set down her bag. “You’ve been up since five, haven’t you?”' || char(10) || '“The house is just quiet,” he said, and turned the photo to face the chair again.'));
INSERT INTO questions (mode, class_id, public, active, data, created_at) SELECT 4, NULL, 1, 1, '{"stem":"Which TWO details show Grandpa is missing someone?","options":[{"id":"a","text":"He straightens the photo for the third time."},{"id":"b","text":"He turns the photo to face the chair."},{"id":"c","text":"He says the house is just quiet."},{"id":"d","text":"Nora sets down her bag.","why":"This is what Nora does, not Grandpa."},{"id":"e","text":"Nora asks a question.","why":"Her question is a clue about Nora’s guess, not Grandpa’s behaviour."},{"id":"f","text":"There is a shelf.","why":"The shelf is only where the photo sits."}],"correct":["a","b","c"],"pick":2,"explanation":"Fussing over the photo three times, turning it towards the chair and mentioning the quiet house all show how much he misses someone.","code":"MC_INFER","context":"“Don’t fuss,” said Grandpa, straightening the photo on the shelf for the third time.\nNora set down her bag. “You’ve been up since five, haven’t you?”\n“The house is just quiet,” he said, and turned the photo to face the chair again.","group":"rbtl-grandpa"}', 1792251314905 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE mode = 4 AND json_extract(data, '$.stem') = ('Which TWO details show Grandpa is missing someone?') AND COALESCE(json_extract(data, '$.context'), '') = ('“Don’t fuss,” said Grandpa, straightening the photo on the shelf for the third time.' || char(10) || 'Nora set down her bag. “You’ve been up since five, haven’t you?”' || char(10) || '“The house is just quiet,” he said, and turned the photo to face the chair again.'));
INSERT INTO questions (mode, class_id, public, active, data, created_at) SELECT 4, NULL, 1, 1, '{"stem":"Why does Nora ask whether he has been up since five?","options":[{"id":"a","text":"She has guessed that he could not sleep because he feels lonely"},{"id":"b","text":"She is checking the time","why":"She is asking about him, not the clock."},{"id":"c","text":"She wants to tell him off for being awake","why":"Her tone is caring, not cross."},{"id":"d","text":"She is hungry and wants breakfast","why":"Food is never mentioned."}],"correct":["a"],"pick":1,"explanation":"She has noticed the signs and is gently trying to get him to talk.","code":"MC_INFER","context":"“Don’t fuss,” said Grandpa, straightening the photo on the shelf for the third time.\nNora set down her bag. “You’ve been up since five, haven’t you?”\n“The house is just quiet,” he said, and turned the photo to face the chair again.","group":"rbtl-grandpa"}', 1792251314905 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE mode = 4 AND json_extract(data, '$.stem') = ('Why does Nora ask whether he has been up since five?') AND COALESCE(json_extract(data, '$.context'), '') = ('“Don’t fuss,” said Grandpa, straightening the photo on the shelf for the third time.' || char(10) || 'Nora set down her bag. “You’ve been up since five, haven’t you?”' || char(10) || '“The house is just quiet,” he said, and turned the photo to face the chair again.'));
